const allowed=['src/miner.mjs','src/errors.mjs','src/decimal.mjs','src/upstream.mjs','src/responses.mjs','src/onchain/routes.mjs','src/onchain/input.mjs','src/onchain/rpc.mjs','src/onchain/verify.mjs','src/unified.mjs','src/weather.mjs','src/v2.mjs','deploy/unified-worker.mjs','deploy/v2-worker.mjs','src/us-place-resolver.mjs','deploy/places-worker.mjs','dist/census/us-places-2026.json'];
