const report={checked_at:new Date().toISOString(),modules:map.sources.length,bundle_bytes:Buffer.byteLength(code),bundle_sha256:sha(code),config_sha256:sha(await readFile('deploy/places.wrangler.jsonc')),assets:assets.map(a=>({file:a.file,sha256:a.sha256})),source_data_sha256:prepared.data_sha256,boundary_passed:true,signing_code_absent:true,evaluation_questions_absent:true,uploaded:false};await writeFile('reports/places-provider/bundle-audit.json',JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify({...report,assets:report.assets.length},null,2));
